(1744117, 236563, 41411, '<td valign="top">This could have been a good shot if you had been more careful with the exposure. A little facial detail would have made a big difference.</td>', 'This could have been a good shot if you had been more careful with the exposure. A little facial detail would have made a big difference.', '2005-09-28 02:21:44.000000', NULL, 1),
(1744120, 236538, 41411, '<td valign="top">It''s a pretty shot, but it''s near impossible to win these contests with macro shots of plants.</td>', 'It''s a pretty shot, but it''s near impossible to win these contests with macro shots of plants.', '2005-09-28 02:22:39.000000', NULL, 1),
