(1744986, 237357, 15711, '<td valign="top">HEE HEE - he is smiling cause he knows something YOU don''t. LOL  I like the perspective and the clarity of his snout. The lighting seems a tad off. I wish the sky were vivid blue. All animal shots get an extra point though.</td>', 'HEE HEE - he is smiling cause he knows something YOU don''t. LOL  I like the perspective and the clarity of his snout. The lighting seems a tad off. I wish the sky were vivid blue. All animal shots get an extra point though.', '2005-09-28 10:40:57.000000', NULL, 1),
(1744987, 237148, 35545, '<td valign="top">Don''t care for the purple sky.  This would have been a good candidate for B&amp;W.</td>', 'Don''t care for the purple sky.  This would have been a good candidate for B&W.', '2005-09-28 10:41:08.000000', NULL, 1),
(1744992, 237290, 41277, '<td valign="top">yep!! its a 10... wait... a 9.. i think if you croped it from the two sides and make it a 2:3 scale image on vertical.. it was perfect!!! geat idea!!</td>', 'yep!! its a 10... wait... a 9.. i think if you croped it from the two sides and make it a 2:3 scale image on vertical.. it was perfect!!! geat idea!!', '2005-09-28 10:41:48.000000', NULL, 1),
