(1748367, 235108, 12223, '<td valign="top">Good color.  Good dof.</td>', 'Good color.  Good dof.', '2005-09-29 14:38:33.000000', NULL, 1),
(1748369, 236968, 37961, '<td valign="top">Lovely sky. Great silhouette.</td>', 'Lovely sky. Great silhouette.', '2005-09-29 14:38:52.000000', NULL, 1),
(1748371, 236795, 37961, '<td valign="top">Wonderful detail, contrast and lighting. Excellent.</td>', 'Wonderful detail, contrast and lighting. Excellent.', '2005-09-29 14:39:44.000000', NULL, 1),
