(1748383, 235889, 42005, '<td valign="top">This photo just makes me happy!</td>', 'This photo just makes me happy!', '2005-09-29 14:47:16.000000', NULL, 1),
(1748386, 237151, 9478, '<td valign="top">Good idea, very nice shot. I should have cropped a bit more not to see the columns and the wall.</td>', 'Good idea, very nice shot. I should have cropped a bit more not to see the columns and the wall.', '2005-09-29 14:49:07.000000', NULL, 1),
