(1749108, 236183, 41675, '<td valign="top">Not as dramatic from the ground up as others, but a very pretty landscape. For me, I wish the horizon was either a bit higher or lower and not so centered. I like the pink hue of the sky reflected in the water.</td>', 'Not as dramatic from the ground up as others, but a very pretty landscape. For me, I wish the horizon was either a bit higher or lower and not so centered. I like the pink hue of the sky reflected in the water.', '2005-09-29 20:44:45.000000', NULL, 1),
(1749111, 236504, 41675, '<td valign="top">Interesting entry for the "Ground Up" challenge. Doesn''t have quite the same impact as the others do, but the reflection in the sunglasses is cool.</td>', 'Interesting entry for the "Ground Up" challenge. Doesn''t have quite the same impact as the others do, but the reflection in the sunglasses is cool.', '2005-09-29 20:45:33.000000', NULL, 1),
