(1749305, 237321, 43400, '<td valign="top">I like the strong perspective, the angle and coloring--very imaginative and different--10</td>', 'I like the strong perspective, the angle and coloring--very imaginative and different--10', '2005-09-29 22:08:11.000000', NULL, 1),
(1749307, 237114, 41675, '<td valign="top">A good, gritty "big apple" feel. Kind of has that timeless quality for me. I like it. The only thing I woule have liked to seen different is maybe cropping out the feet and base of the pole in the upper right corner.</td>', 'A good, gritty "big apple" feel. Kind of has that timeless quality for me. I like it. The only thing I woule have liked to seen different is maybe cropping out the feet and base of the pole in the upper right corner.', '2005-09-29 22:08:32.000000', NULL, 1),
(1749309, 235446, 41675, '<td valign="top">It''s too bad the sky was overcast when you shot this. I bet the colors on the ride buckets would have been even more vivid. I do like your "ground up" view though - cool.</td>', 'It''s too bad the sky was overcast when you shot this. I bet the colors on the ride buckets would have been even more vivid. I do like your "ground up" view though - cool.', '2005-09-29 22:09:19.000000', NULL, 1),
(1749310, 237221, 43156, '<td valign="top">Great picture, fits the challenge; just little too dark and border too big</td>', 'Great picture, fits the challenge; just little too dark and border too big', '2005-09-29 22:09:56.000000', NULL, 1),
