(1749312, 236827, 43400, '<td valign="top">clever idea-just wish it was more clear and defined w/o effects</td>', 'clever idea-just wish it was more clear and defined w/o effects', '2005-09-29 22:10:16.000000', NULL, 1),
(1749314, 235884, 41675, '<td valign="top">Neat photo. I always enjoy seeing staircases vieweed from below or above. I find that spotlight distracting, but I know you had no control over that, especially in an open challenge. Nicely done in my opinion.</td>', 'Neat photo. I always enjoy seeing staircases vieweed from below or above. I find that spotlight distracting, but I know you had no control over that, especially in an open challenge. Nicely done in my opinion.', '2005-09-29 22:11:09.000000', NULL, 1),
(1749319, 237170, 43156, '<td valign="top">Cute cat just a little out of focus</td>', 'Cute cat just a little out of focus', '2005-09-29 22:13:08.000000', NULL, 1),
(1749326, 237019, 43400, '<td valign="top">I like the lighting (flash?) on this contrasting the textured sky.. I think the bushes are the weakest elements, but overall good capture.</td>', 'I like the lighting (flash?) on this contrasting the textured sky.. I think the bushes are the weakest elements, but overall good capture.', '2005-09-29 22:14:48.000000', NULL, 1),
(1749335, 236008, 43400, '<td valign="top">Nice capture in B&amp;W, but think it fits the theme. The tree? in background looks a little creepy that almost works in this composition</td>', 'Nice capture in B&W, but think it fits the theme. The tree? in background looks a little creepy that almost works in this composition', '2005-09-29 22:17:32.000000', NULL, 1),
(1749340, 236921, 43400, '<td valign="top">Cool perspective and probably be great in monochromatic tones. Great capture!</td>', 'Cool perspective and probably be great in monochromatic tones. Great capture!', '2005-09-29 22:19:19.000000', NULL, 1),
(1749341, 237228, 41675, '<td valign="top">Fun concept and notion. I like it. I also like the lighting. Hope you do well in the challenge.</td>', 'Fun concept and notion. I like it. I also like the lighting. Hope you do well in the challenge.', '2005-09-29 22:20:06.000000', NULL, 1),
(1749345, 237262, 41675, '<td valign="top">A respectful photo. It doesn''t pop or have that wow factor of other entries in this challenge, but it''s nice.</td>', 'A respectful photo. It doesn''t pop or have that wow factor of other entries in this challenge, but it''s nice.', '2005-09-29 22:21:39.000000', NULL, 1),
(1749346, 237151, 41675, '<td valign="top">Very nice ceiling. I like the interior and colors.</td>', 'Very nice ceiling. I like the interior and colors.', '2005-09-29 22:22:17.000000', NULL, 1),
(1749348, 237389, 41675, '<td valign="top">Nice arch photo. The highlight in the lower right is a bit too bright, but great sky. Such a photogenic structure.</td>', 'Nice arch photo. The highlight in the lower right is a bit too bright, but great sky. Such a photogenic structure.', '2005-09-29 22:23:04.000000', NULL, 1),
(1749349, 236144, 43565, '<td valign="top">This is not from the ground up IMO.</td>', 'This is not from the ground up IMO.', '2005-09-29 22:24:29.000000', NULL, 1),
(1749352, 236108, 43400, '<td valign="top">Interest capture of windmill--but more intersting if propellar was turning (captured at slower shutter) showing some action. The pole blend so much to the sky that it disttracts from the whole composition as if the propellar has no visual/physical support. Great potential.</td>', 'Interest capture of windmill--but more intersting if propellar was turning (captured at slower shutter) showing some action. The pole blend so much to the sky that it disttracts from the whole composition as if the propellar has no visual/physical support. Great potential.', '2005-09-29 22:25:22.000000', NULL, 1),
(1749353, 234989, 43565, '<td valign="top">IMO this does not look like it was shot from the gound up.</td>', 'IMO this does not look like it was shot from the gound up.', '2005-09-29 22:25:58.000000', NULL, 1),
