INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1749365, 236303, 43400, '<td valign="top">Blade Runner, Odyssey 2001, Flash Gordon,...whatever spacecraft--- LOVE IT! By the way, there''s a hotel in Times Square that has the same type elevators and admire the engineering of ''em. --Great capture and coolperspective --one of my favoraites so far.</td>', 'Blade Runner, Odyssey 2001, Flash Gordon,...whatever spacecraft--- LOVE IT! By the way, there''s a hotel in Times Square that has the same type elevators and admire the engineering of ''em. --Great capture and coolperspective --one of my favoraites so far.', '2005-09-29 22:32:40.000000', NULL, 1),
(1749368, 236420, 43565, '<td valign="top"></td>', '', '2005-09-29 22:33:08.000000', NULL, 1),
(1749371, 237084, 41675, '<td valign="top">The sky seems overly lit to me. I like the rest of the photo. My favorite part being the way the "hairs" on the stem are backlit. A nice color on the red flowers too.</td>', 'The sky seems overly lit to me. I like the rest of the photo. My favorite part being the way the "hairs" on the stem are backlit. A nice color on the red flowers too.', '2005-09-29 22:34:17.000000', NULL, 1),
(1749373, 236117, 43565, '<td valign="top">I would prefer more of a feeling of looking up.</td>', 'I would prefer more of a feeling of looking up.', '2005-09-29 22:34:22.000000', NULL, 1),
(1749375, 236102, 43565, '<td valign="top">I would like to see the dog more in focus.</td>', 'I would like to see the dog more in focus.', '2005-09-29 22:34:46.000000', NULL, 1),
(1749376, 236460, 43400, '<td valign="top">Very graphic, like a corporate brochure--truly like it alot. Great symmetry contrasts, reflections and tones--good work</td>', 'Very graphic, like a corporate brochure--truly like it alot. Great symmetry contrasts, reflections and tones--good work', '2005-09-29 22:34:59.000000', NULL, 1),
(1749377, 237300, 41675, '<td valign="top">Such amazing and graceful birds. A very nice capture and nicely focused. I like the clarity of the eye. Great solid blue sky also. Good luck in the challenge.</td>', 'Such amazing and graceful birds. A very nice capture and nicely focused. I like the clarity of the eye. Great solid blue sky also. Good luck in the challenge.', '2005-09-29 22:35:01.000000', NULL, 1),
(1749382, 237395, 41675, '<td valign="top">Nice birch trees and foliage - makes me homesick for the northeast.</td>', 'Nice birch trees and foliage - makes me homesick for the northeast.', '2005-09-29 22:35:26.000000', NULL, 1),
(1749383, 235105, 41675, '<td valign="top">I like the subject. I wish there was some sort of object hanging off the post thought. That would add interest for me.</td>', 'I like the subject. I wish there was some sort of object hanging off the post thought. That would add interest for me.', '2005-09-29 22:36:05.000000', NULL, 1),
(1749389, 236885, 41675, '<td valign="top">Good to see a different kind of entry in the challenge. She definitely does not have a fear of heights. I like how the mast leads the eyes up to her. Wish there was a bit more color though - seems close to monochromatic.</td>', 'Good to see a different kind of entry in the challenge. She definitely does not have a fear of heights. I like how the mast leads the eyes up to her. Wish there was a bit more color though - seems close to monochromatic.', '2005-09-29 22:37:28.000000', NULL, 1),
(1749409, 235515, 41675, '<td valign="top">So far, one of my favorites in this challenge. I like the striking black and whites. Spooky looking sky too. Well done. Hope it does well.</td>', 'So far, one of my favorites in this challenge. I like the striking black and whites. Spooky looking sky too. Well done. Hope it does well.', '2005-09-29 22:46:32.000000', NULL, 1),
(1749412, 236688, 41675, '<td valign="top">For me, I like to see the main subjects slightly more off center as it adds more interest to the viewer. My favorite part is in the very upper left corner and the pattern of the branches against the blue of the sky.</td>', 'For me, I like to see the main subjects slightly more off center as it adds more interest to the viewer. My favorite part is in the very upper left corner and the pattern of the branches against the blue of the sky.', '2005-09-29 22:47:49.000000', NULL, 1),
(1749415, 237312, 41675, '<td valign="top">Very nice action shot. The only thing I would like to see would perhaps be a black hairline border along the very edge of the photo itself. Hope you get a ribbon. 10</td>', 'Very nice action shot. The only thing I would like to see would perhaps be a black hairline border along the very edge of the photo itself. Hope you get a ribbon. 10', '2005-09-29 22:48:42.000000', NULL, 1),
(1749417, 235245, 41675, '<td valign="top">I like how the vehicle looks so small compared to the surroundings. I wish there was a bit more color in the mountain in the background, but still a good photo.</td>', 'I like how the vehicle looks so small compared to the surroundings. I wish there was a bit more color in the mountain in the background, but still a good photo.', '2005-09-29 22:49:36.000000', NULL, 1),
(1749420, 236573, 41675, '<td valign="top">Great church shot. The skin tones seem just a bit on the megenta side, but otherwise I really, really like this photo. Good luck in the challenge - hope you do well. 9</td>', 'Great church shot. The skin tones seem just a bit on the megenta side, but otherwise I really, really like this photo. Good luck in the challenge - hope you do well. 9', '2005-09-29 22:50:24.000000', NULL, 1),
(1749424, 237335, 41675, '<td valign="top">Wow - what a toxic green sky. I like the framing created by the trees, but the sky is a bit too sureal for my tastes.</td>', 'Wow - what a toxic green sky. I like the framing created by the trees, but the sky is a bit too sureal for my tastes.', '2005-09-29 22:51:02.000000', NULL, 1),
(1749443, 237221, 44172, '<td valign="top">I really like this! my preference would be an even border though - too thick on top and bottom - a little distracting - but the photo is very interesting...</td>', 'I really like this! my preference would be an even border though - too thick on top and bottom - a little distracting - but the photo is very interesting...', '2005-09-29 22:59:53.000000', NULL, 1),
(1749445, 235917, 44172, '<td valign="top">nice photo, not sure about ground up...</td>', 'nice photo, not sure about ground up...', '2005-09-29 23:01:24.000000', NULL, 1),
(1749452, 236162, 44172, '<td valign="top">funny - good title</td>', 'funny - good title', '2005-09-29 23:03:18.000000', NULL, 1),
(1749455, 235510, 41675, '<td valign="top">Great vivid colors...I can almost smell the fried foods (ha ha). It seems a bit too closely cropped on the left side, but I still really like it. Godo job. Fun photo.</td>', 'Great vivid colors...I can almost smell the fried foods (ha ha). It seems a bit too closely cropped on the left side, but I still really like it. Godo job. Fun photo.', '2005-09-29 23:05:45.000000', NULL, 1),
(1749456, 237407, 41675, '<td valign="top">This must be the fair time of year, as this is the third shot in a row I''ve voted on. For me, this photo appears more of a direct or side view rather than from the ground up, but I really, really like the colors of that sky - tremendous.</td>', 'This must be the fair time of year, as this is the third shot in a row I''ve voted on. For me, this photo appears more of a direct or side view rather than from the ground up, but I really, really like the colors of that sky - tremendous.', '2005-09-29 23:06:57.000000', NULL, 1),
(1749461, 237398, 41675, '<td valign="top">For me, I think this would be better if cropped in much tighter from the left hand side, thus off centering the main subject and adding more interest. Very cool building though, and I like the lighting and sky.</td>', 'For me, I think this would be better if cropped in much tighter from the left hand side, thus off centering the main subject and adding more interest. Very cool building though, and I like the lighting and sky.', '2005-09-29 23:08:07.000000', NULL, 1),
(1749465, 237275, 44172, '<td valign="top">very nice photo...wonder where it is - my toddler would LOVE it here!!!</td>', 'very nice photo...wonder where it is - my toddler would LOVE it here!!!', '2005-09-29 23:09:58.000000', NULL, 1),
(1749486, 236979, 41675, '<td valign="top">neat sail...and...trails. Too bad about the overcast sky. I bet those colors would have been even more vibrant.</td>', 'neat sail...and...trails. Too bad about the overcast sky. I bet those colors would have been even more vibrant.', '2005-09-29 23:22:19.000000', NULL, 1),
(1749491, 235800, 41675, '<td valign="top">For me, there is a bit too much of the wall. Such a great sky, had there been an even steeper angle from beneath the guitarist I would have scored it higher.</td>', 'For me, there is a bit too much of the wall. Such a great sky, had there been an even steeper angle from beneath the guitarist I would have scored it higher.', '2005-09-29 23:23:15.000000', NULL, 1),
(1749493, 235594, 41675, '<td valign="top">Nice, simple, clean shot from below. Well lit and good colors and clarity.</td>', 'Nice, simple, clean shot from below. Well lit and good colors and clarity.', '2005-09-29 23:23:49.000000', NULL, 1),
(1749495, 237382, 39821, '<td valign="top">I like the orderliness.  I have also seen installations of electrical conduit that have looked like art.</td>', 'I like the orderliness.  I have also seen installations of electrical conduit that have looked like art.', '2005-09-29 23:24:24.000000', NULL, 1),
(1749496, 236483, 41675, '<td valign="top">I really like the smile on the woman''s face - it shows a true joy towards the oncoming girl. I don''t get as great a sense of "from the ground up" as other photos, but I really like the overall treatment.</td>', 'I really like the smile on the woman''s face - it shows a true joy towards the oncoming girl. I don''t get as great a sense of "from the ground up" as other photos, but I really like the overall treatment.', '2005-09-29 23:25:02.000000', NULL, 1),
(1749501, 236746, 39821, '<td valign="top">I like the soft color transitions along with the wide-open feeling.</td>', 'I like the soft color transitions along with the wide-open feeling.', '2005-09-29 23:26:28.000000', NULL, 1),
(1749518, 236031, 41675, '<td valign="top">Nice architectural photo and good lighting.</td>', 'Nice architectural photo and good lighting.', '2005-09-29 23:34:55.000000', NULL, 1),
(1749522, 234989, 41675, '<td valign="top">For me, this shot might have been more successful with the horizon not in the dead center of the photo and taken at a steeper angle. The sun itself is quite breathtaking.</td>', 'For me, this shot might have been more successful with the horizon not in the dead center of the photo and taken at a steeper angle. The sun itself is quite breathtaking.', '2005-09-29 23:36:25.000000', NULL, 1),
(1749524, 236937, 41675, '<td valign="top">All of your elements lead my eyes to the upper middle, but when my eyes go there it''s void and I feel a bit disappointed. Interesting structure though.</td>', 'All of your elements lead my eyes to the upper middle, but when my eyes go there it''s void and I feel a bit disappointed. Interesting structure though.', '2005-09-29 23:37:28.000000', NULL, 1),
(1749526, 236223, 41675, '<td valign="top">Your photo definitely gives a sense of height. Good blue sky color. I can''t quite decide if the tree on the right is effective or would the photo be more effective without it?</td>', 'Your photo definitely gives a sense of height. Good blue sky color. I can''t quite decide if the tree on the right is effective or would the photo be more effective without it?', '2005-09-29 23:38:41.000000', NULL, 1),
(1749528, 237352, 36619, '<td valign="top">remarkable photo.</td>', 'remarkable photo.', '2005-09-29 23:41:16.000000', NULL, 1),
(1749533, 235479, 36619, '<td valign="top">great angle and subject, it just seems to br missing something to make it pop, maybe if she was leaning over the edge a little or wearing something brighter.</td>', 'great angle and subject, it just seems to br missing something to make it pop, maybe if she was leaning over the edge a little or wearing something brighter.', '2005-09-29 23:45:10.000000', NULL, 1),
(1749537, 237019, 40344, '<td valign="top">An engaging photo, I''d like it even better with the bottom quarter cropped.</td>', 'An engaging photo, I''d like it even better with the bottom quarter cropped.', '2005-09-29 23:47:07.000000', NULL, 1),
(1749539, 237025, 41675, '<td valign="top">Ha ha ha. This guy reminds me more of a happy viking than a genie. Fun photo.</td>', 'Ha ha ha. This guy reminds me more of a happy viking than a genie. Fun photo.', '2005-09-29 23:47:25.000000', NULL, 1),
(1749569, 235726, 42013, '<td valign="top">nice color tones</td>', 'nice color tones', '2005-09-30 00:04:08.000000', NULL, 1),
(1749576, 237374, 41675, '<td valign="top">I love the vibrant colors. Great below the dog view. I feel as if I''m about to be sniffed. :-) 10</td>', 'I love the vibrant colors. Great below the dog view. I feel as if I''m about to be sniffed. :-) 10', '2005-09-30 00:06:34.000000', NULL, 1),
(1749578, 236753, 41675, '<td valign="top">I don''t know why, but I feel as if something is about to roll down at me. mabye it''s the curve of the building or the lack of focus, I''m not sure which. My favorite part is the blue sky and clouds.</td>', 'I don''t know why, but I feel as if something is about to roll down at me. mabye it''s the curve of the building or the lack of focus, I''m not sure which. My favorite part is the blue sky and clouds.', '2005-09-30 00:07:55.000000', NULL, 1),
(1749581, 237069, 41675, '<td valign="top">For me, this would have been even more dramatic if it was taken from an even lower angle - If you were truly on the ground and looking up. Too bad about the guy in between the two main subjects as He''s a bit of a distraction to me.</td>', 'For me, this would have been even more dramatic if it was taken from an even lower angle - If you were truly on the ground and looking up. Too bad about the guy in between the two main subjects as He''s a bit of a distraction to me.', '2005-09-30 00:09:03.000000', NULL, 1),
