(1750892, 237335, 41574, '<td valign="top">The colors seem off. Is this how the shot was intended to be?</td>', 'The colors seem off. Is this how the shot was intended to be?', '2005-09-30 18:20:37.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1750893, 237128, 41574, '<td valign="top">Amazing... I think it''s straying a bit too far from the topic, but it is a gorgeous shot.</td>', 'Amazing... I think it''s straying a bit too far from the topic, but it is a gorgeous shot.', '2005-09-30 18:21:17.000000', NULL, 1),
(1750894, 236999, 44914, '<td valign="top">great image</td>', 'great image', '2005-09-30 18:21:42.000000', NULL, 1),
(1750897, 236827, 41574, '<td valign="top">I get the concept, but the image just seems too dull. That is, I like what you''re saying, but I''m not particularly fond of the way you''re saying it.</td>', 'I get the concept, but the image just seems too dull. That is, I like what you''re saying, but I''m not particularly fond of the way you''re saying it.', '2005-09-30 18:22:17.000000', NULL, 1),
(1750899, 236194, 41574, '<td valign="top">Awesome.</td>', 'Awesome.', '2005-09-30 18:22:27.000000', NULL, 1),
(1750900, 237119, 44914, '<td valign="top">awesome angle,geat photo!</td>', 'awesome angle,geat photo!', '2005-09-30 18:22:30.000000', NULL, 1),
(1750901, 236868, 41574, '<td valign="top">I don''t really see anything of interest here.</td>', 'I don''t really see anything of interest here.', '2005-09-30 18:22:48.000000', NULL, 1),
(1750902, 237076, 41574, '<td valign="top">Very nice.</td>', 'Very nice.', '2005-09-30 18:23:00.000000', NULL, 1),
(1750903, 235008, 41574, '<td valign="top">Great. I love the symmetry.</td>', 'Great. I love the symmetry.', '2005-09-30 18:23:28.000000', NULL, 1),
(1750905, 237230, 44914, '<td valign="top">amazing landscape!</td>', 'amazing landscape!', '2005-09-30 18:24:08.000000', NULL, 1),
(1750906, 235173, 41574, '<td valign="top">I feel that the background is too focused, and too bright. I like, however, that the subject is within the depth-of-field.</td>', 'I feel that the background is too focused, and too bright. I like, however, that the subject is within the depth-of-field.', '2005-09-30 18:24:47.000000', NULL, 1),
(1750907, 236483, 41574, '<td valign="top">Nice; very "Hallmark."</td>', 'Nice; very "Hallmark."', '2005-09-30 18:25:13.000000', NULL, 1),
(1750908, 237375, 44914, '<td valign="top">was this a fisheye lens?great angle and photo!</td>', 'was this a fisheye lens?great angle and photo!', '2005-09-30 18:25:30.000000', NULL, 1),
(1750909, 236420, 41574, '<td valign="top">I don''t see anything of interest here, and it doesn''t really adhere to the "ground up" concept.</td>', 'I don''t see anything of interest here, and it doesn''t really adhere to the "ground up" concept.', '2005-09-30 18:25:54.000000', NULL, 1),
(1750913, 237372, 41574, '<td valign="top">Beautiful colors. I absolutely love the sky. Also, superb composition.</td>', 'Beautiful colors. I absolutely love the sky. Also, superb composition.', '2005-09-30 18:26:40.000000', NULL, 1),
(1750914, 236460, 41574, '<td valign="top">It''s very nice, but the dead-center framing makes the picture somewhat boring.</td>', 'It''s very nice, but the dead-center framing makes the picture somewhat boring.', '2005-09-30 18:27:18.000000', NULL, 1),
(1750916, 237114, 41574, '<td valign="top">Diggin'' the B&amp;W.</td>', 'Diggin'' the B&W.', '2005-09-30 18:28:08.000000', NULL, 1),
(1750917, 237188, 44914, '<td valign="top">nice colour and sharp image.</td>', 'nice colour and sharp image.', '2005-09-30 18:28:17.000000', NULL, 1),
(1750920, 234972, 44914, '<td valign="top">Great composition</td>', 'Great composition', '2005-09-30 18:29:36.000000', NULL, 1),
(1750921, 236492, 41574, '<td valign="top">Great macro, but I think trying to apply it to the theme is a bit of a stretch. Really the only relation is in the title. I''d give you a "9" for the image, and a "2" for sticking to the theme; I''ll go ahead and give you a "6."</td>', 'Great macro, but I think trying to apply it to the theme is a bit of a stretch. Really the only relation is in the title. I''d give you a "9" for the image, and a "2" for sticking to the theme; I''ll go ahead and give you a "6."', '2005-09-30 18:29:44.000000', NULL, 1),
(1750924, 237143, 44914, '<td valign="top">great close up! uaaggh, not keen on big spiders</td>', 'great close up! uaaggh, not keen on big spiders', '2005-09-30 18:30:51.000000', NULL, 1),
(1750926, 236468, 41574, '<td valign="top">I can appreciate minimalism at its best, but I''m sorry to say that I don''t think this is it. The red kite is over-saturated (as is the entire picture, it''s just very noticeable with the red kite), and it seems that the shutter was kept open too long, and the subject is not quite in focus.</td>', 'I can appreciate minimalism at its best, but I''m sorry to say that I don''t think this is it. The red kite is over-saturated (as is the entire picture, it''s just very noticeable with the red kite), and it seems that the shutter was kept open too long, and the subject is not quite in focus.', '2005-09-30 18:31:33.000000', NULL, 1),
(1750928, 237309, 41574, '<td valign="top">Awesome concept for the theme. Nice photo, too.</td>', 'Awesome concept for the theme. Nice photo, too.', '2005-09-30 18:31:52.000000', NULL, 1),
(1750929, 237004, 41574, '<td valign="top">I love how you''ve framed this shot (through the arch). The exposure, too, is superb. The best part, though, is the subject: Clear, interesting, great.</td>', 'I love how you''ve framed this shot (through the arch). The exposure, too, is superb. The best part, though, is the subject: Clear, interesting, great.', '2005-09-30 18:32:59.000000', NULL, 1),
(1750930, 237312, 44914, '<td valign="top">wow! great action!!!</td>', 'wow! great action!!!', '2005-09-30 18:33:15.000000', NULL, 1),
(1750931, 235924, 41574, '<td valign="top">I think I might''ve liked to see the kid climbing up the slide, but this, too, is nice.</td>', 'I think I might''ve liked to see the kid climbing up the slide, but this, too, is nice.', '2005-09-30 18:33:40.000000', NULL, 1),
(1750933, 237010, 41574, '<td valign="top">Nauseous. I love it.</td>', 'Nauseous. I love it.', '2005-09-30 18:34:18.000000', NULL, 1),
(1750934, 237289, 41574, '<td valign="top">Very nice. You got a great angle.</td>', 'Very nice. You got a great angle.', '2005-09-30 18:34:54.000000', NULL, 1),
(1750937, 236735, 41574, '<td valign="top">Not only do things look under-exposed, they don''t look very sharp. Nice idea, though.</td>', 'Not only do things look under-exposed, they don''t look very sharp. Nice idea, though.', '2005-09-30 18:35:41.000000', NULL, 1),
(1750941, 237013, 41574, '<td valign="top">Oh, my god: amazing. I can feel the warmth, and it''s like 60 degrees (F) in this room. I''d love an 800X600 copy to use as my wallpaper.</td>', 'Oh, my god: amazing. I can feel the warmth, and it''s like 60 degrees (F) in this room. I''d love an 800X600 copy to use as my wallpaper.', '2005-09-30 18:36:39.000000', NULL, 1),
(1750944, 237171, 41574, '<td valign="top">Wow, this is one of the more creative shots I''ve seen. Most seem to be of architecture, but I think this is the only statue I''ve seen. Furthermore, the perspective is creative. You, sir (or madam), are c-r-e-a-t-i-v-e.</td>', 'Wow, this is one of the more creative shots I''ve seen. Most seem to be of architecture, but I think this is the only statue I''ve seen. Furthermore, the perspective is creative. You, sir (or madam), are c-r-e-a-t-i-v-e.', '2005-09-30 18:37:54.000000', NULL, 1),
(1750946, 237069, 41574, '<td valign="top">I''d say the concept is better than the photograph, but the latter''s not bad, either.</td>', 'I''d say the concept is better than the photograph, but the latter''s not bad, either.', '2005-09-30 18:38:33.000000', NULL, 1),
(1750948, 235216, 41574, '<td valign="top">I find the glare to the top-left of the frame distracting (the bottom-right poses a small problem, as well). Other than that, I love the frozen motion, and I like how it fits with the theme. Good job.</td>', 'I find the glare to the top-left of the frame distracting (the bottom-right poses a small problem, as well). Other than that, I love the frozen motion, and I like how it fits with the theme. Good job.', '2005-09-30 18:39:39.000000', NULL, 1),
(1750949, 237357, 41574, '<td valign="top">Amazing. Nice to see a dog shot that still works with the requirement of the challenge.</td>', 'Amazing. Nice to see a dog shot that still works with the requirement of the challenge.', '2005-09-30 18:40:20.000000', NULL, 1),
(1750951, 234919, 41574, '<td valign="top">It''s nice, but boring. Amidst all the building shots in this challenge, this picture just doesn''t manage to stand out. Sorry.</td>', 'It''s nice, but boring. Amidst all the building shots in this challenge, this picture just doesn''t manage to stand out. Sorry.', '2005-09-30 18:41:04.000000', NULL, 1),
(1750953, 237054, 41574, '<td valign="top">A very nice picture, and a creative use of your religious beliefs. It meshes very well with "ground up."</td>', 'A very nice picture, and a creative use of your religious beliefs. It meshes very well with "ground up."', '2005-09-30 18:41:42.000000', NULL, 1),
(1750957, 235315, 41574, '<td valign="top">I wish the sky weren''t so blown out (it even offends the neighboring bit of edifice), but I really like the cannon/fort thing. Good. I''d like to give it an "8," but that sky''s going to force a "7" out of me. Sorry.</td>', 'I wish the sky weren''t so blown out (it even offends the neighboring bit of edifice), but I really like the cannon/fort thing. Good. I''d like to give it an "8," but that sky''s going to force a "7" out of me. Sorry.', '2005-09-30 18:43:08.000000', NULL, 1),
(1750960, 236504, 41574, '<td valign="top">I don''t really see how this fits the "ground up" concept.</td>', 'I don''t really see how this fits the "ground up" concept.', '2005-09-30 18:43:52.000000', NULL, 1),
(1750961, 235909, 41574, '<td valign="top">Very endearing.</td>', 'Very endearing.', '2005-09-30 18:44:03.000000', NULL, 1),
(1750967, 237022, 41574, '<td valign="top">Amongst some very tought competition, I think we have a winner. This photograoh makes me wish there were an "11." Just out of curiousity, is the bicycle in motion, or is it static?</td>', 'Amongst some very tought competition, I think we have a winner. This photograoh makes me wish there were an "11." Just out of curiousity, is the bicycle in motion, or is it static?', '2005-09-30 18:46:22.000000', NULL, 1),
(1750968, 235762, 41574, '<td valign="top">My only real complaint is that the background is not out-of-focus enough. You might have tried a wider aperture, but perhaps this was the widest you had. Anyway, good job.</td>', 'My only real complaint is that the background is not out-of-focus enough. You might have tried a wider aperture, but perhaps this was the widest you had. Anyway, good job.', '2005-09-30 18:47:31.000000', NULL, 1),
(1750972, 237286, 41574, '<td valign="top">The upper region of the shot fails to captivate.</td>', 'The upper region of the shot fails to captivate.', '2005-09-30 18:48:13.000000', NULL, 1),
(1750978, 236094, 41574, '<td valign="top">Amidst a slew of buildings, this somehow manages to stand out. Great job.</td>', 'Amidst a slew of buildings, this somehow manages to stand out. Great job.', '2005-09-30 18:49:06.000000', NULL, 1),
(1750983, 234989, 41574, '<td valign="top">Love the picture, don''t really get its relation to the topic.</td>', 'Love the picture, don''t really get its relation to the topic.', '2005-09-30 18:49:34.000000', NULL, 1),
(1750986, 236563, 41574, '<td valign="top">Nice, but blurry (though, maybe [likely] that''s what you were going for).</td>', 'Nice, but blurry (though, maybe [likely] that''s what you were going for).', '2005-09-30 18:50:30.000000', NULL, 1),
(1750991, 237261, 41574, '<td valign="top">How, exactly, does this relate to the "ground-up" theme? It''s got some beautiful colors, but I''m lost as to the relation.</td>', 'How, exactly, does this relate to the "ground-up" theme? It''s got some beautiful colors, but I''m lost as to the relation.', '2005-09-30 18:52:20.000000', NULL, 1),
(1750996, 236971, 19633, '<td valign="top">I can''t decide if this picture would be better without the tree or not. I definitely think it would be better without the shadow on the building in the lower right hand corner.</td>', 'I can''t decide if this picture would be better without the tree or not. I definitely think it would be better without the shadow on the building in the lower right hand corner.', '2005-09-30 18:56:23.000000', NULL, 1),
(1751000, 234867, 19633, '<td valign="top">I don''t think the "bullseye" approach to composition works as well as it could with this subject. For it to work well, the background would have to have almost no detail, I think.</td>', 'I don''t think the "bullseye" approach to composition works as well as it could with this subject. For it to work well, the background would have to have almost no detail, I think.', '2005-09-30 18:58:33.000000', NULL, 1),
(1751002, 236921, 19633, '<td valign="top">The complimentary colors in this image are excellent. I also like hte slightly off center composition. It''s much more dramatic than a "bullseye."</td>', 'The complimentary colors in this image are excellent. I also like hte slightly off center composition. It''s much more dramatic than a "bullseye."', '2005-09-30 18:59:33.000000', NULL, 1),
(1751003, 235116, 19633, '<td valign="top">Nice flare. Would the picture have been better w/o all the blue? Just wondering...</td>', 'Nice flare. Would the picture have been better w/o all the blue? Just wondering...', '2005-09-30 19:00:08.000000', NULL, 1),
(1751004, 237160, 19633, '<td valign="top">Nice use of line. Classic composition.</td>', 'Nice use of line. Classic composition.', '2005-09-30 19:00:31.000000', NULL, 1),
(1751008, 235556, 19633, '<td valign="top">The subject is great. I only wish the light hadn''t been so harsh.</td>', 'The subject is great. I only wish the light hadn''t been so harsh.', '2005-09-30 19:01:11.000000', NULL, 1),
(1751014, 235433, 19633, '<td valign="top">My eye struggles with this composition. The big boulder in the middle carries the most weight, but I suspect that it''s not what you want us to look at.</td>', 'My eye struggles with this composition. The big boulder in the middle carries the most weight, but I suspect that it''s not what you want us to look at.', '2005-09-30 19:03:12.000000', NULL, 1),
(1751016, 236982, 19633, '<td valign="top">I''m strangely drawn to the symmetry of the picture.</td>', 'I''m strangely drawn to the symmetry of the picture.', '2005-09-30 19:04:35.000000', NULL, 1),
(1751019, 237308, 19633, '<td valign="top">Oh, I so wanted the focus to be the exact opposite of what it is.</td>', 'Oh, I so wanted the focus to be the exact opposite of what it is.', '2005-09-30 19:05:10.000000', NULL, 1),
(1751024, 236732, 19633, '<td valign="top">There is nice tension in the photo with the dog looking at something off camera. The effect is ruined slightly by the tree.</td>', 'There is nice tension in the photo with the dog looking at something off camera. The effect is ruined slightly by the tree.', '2005-09-30 19:07:12.000000', NULL, 1),
(1751028, 236108, 24642, '<td valign="top">Nice colors and composition.</td>', 'Nice colors and composition.', '2005-09-30 19:08:59.000000', NULL, 1),
(1751029, 235438, 19633, '<td valign="top">Did you use the zoom and a long exposure while you were taking this picture? It''s awesome!</td>', 'Did you use the zoom and a long exposure while you were taking this picture? It''s awesome!', '2005-09-30 19:09:30.000000', NULL, 1),
(1751034, 237352, 19633, '<td valign="top">One of the nicer tree pictures in the challenge. The color works well.</td>', 'One of the nicer tree pictures in the challenge. The color works well.', '2005-09-30 19:10:42.000000', NULL, 1),
(1751036, 235655, 19633, '<td valign="top">Ohhh! Love the color. Nice macro.</td>', 'Ohhh! Love the color. Nice macro.', '2005-09-30 19:11:10.000000', NULL, 1),
(1751039, 235452, 19633, '<td valign="top">With a title like that, I expected to see something that a cat would go after (bird, fly, mouse, spider). Alas, no such luck.</td>', 'With a title like that, I expected to see something that a cat would go after (bird, fly, mouse, spider). Alas, no such luck.', '2005-09-30 19:12:45.000000', NULL, 1),
(1751045, 236602, 19633, '<td valign="top">Nice use of color. I also like the contrast between the formal lines of the building / flag poles and the flowing lines of the flags themselves.</td>', 'Nice use of color. I also like the contrast between the formal lines of the building / flag poles and the flowing lines of the flags themselves.', '2005-09-30 19:15:27.000000', NULL, 1),
(1751047, 236468, 19633, '<td valign="top">Dang...couldn''t the green or yellow flag been pointing up instead of the red?</td>', 'Dang...couldn''t the green or yellow flag been pointing up instead of the red?', '2005-09-30 19:16:54.000000', NULL, 1),
(1751051, 236303, 19633, '<td valign="top">Mariott Marquis in Times Square, right?!</td>', 'Mariott Marquis in Times Square, right?!', '2005-09-30 19:21:37.000000', NULL, 1),
(1751052, 236468, 43565, '<td valign="top">This just doesn''t get my interest.</td>', 'This just doesn''t get my interest.', '2005-09-30 19:22:17.000000', NULL, 1),
