(1751058, 236432, 43565, '<td valign="top">IMO, more post processing would have helped, or maybe done in black and white.</td>', 'IMO, more post processing would have helped, or maybe done in black and white.', '2005-09-30 19:27:34.000000', NULL, 1),
(1751059, 236999, 9478, '<td valign="top">One of my favourites. Phantastic!</td>', 'One of my favourites. Phantastic!', '2005-09-30 19:28:22.000000', NULL, 1),
(1751060, 236400, 9478, '<td valign="top">I really like the light and colour of the ceiling. This must be a ribbon.</td>', 'I really like the light and colour of the ceiling. This must be a ribbon.', '2005-09-30 19:29:18.000000', NULL, 1),
(1751061, 235728, 9478, '<td valign="top">Very good! Top ten for me.</td>', 'Very good! Top ten for me.', '2005-09-30 19:29:49.000000', NULL, 1),
(1751062, 237299, 9478, '<td valign="top">It''s out of focus and I think it does not fit in the challenge.</td>', 'It''s out of focus and I think it does not fit in the challenge.', '2005-09-30 19:31:23.000000', NULL, 1),
(1751065, 236477, 43565, '<td valign="top">To me this does have a perspective of from the ground UP.</td>', 'To me this does have a perspective of from the ground UP.', '2005-09-30 19:32:22.000000', NULL, 1),
