(1751564, 236495, 41574, '<td valign="top">Shot seems just a tad under-exposed. Other than that, it''s fine.</td>', 'Shot seems just a tad under-exposed. Other than that, it''s fine.', '2005-10-01 00:36:39.000000', NULL, 1),
(1751569, 236992, 41574, '<td valign="top">It''s a good idea for this theme, but it''s just not a very stunning photograph. The background is totally blank, lacking any interest; the subject doesn''t really seem high enough to be distant, or intense enough to be enthralling; and the environment  which one might assume would play a large part in such a picture  is virtually nonexistent. Sorry if I was harsh, but I think it could''ve been better.</td>', 'It''s a good idea for this theme, but it''s just not a very stunning photograph. The background is totally blank, lacking any interest; the subject doesn''t really seem high enough to be distant, or intense enough to be enthralling; and the environment  which one might assume would play a large part in such a picture  is virtually nonexistent. Sorry if I was harsh, but I think it could''ve been better.', '2005-10-01 00:38:42.000000', NULL, 1),
(1751571, 236403, 41574, '<td valign="top">One of the (few) flower shots that actually manage to fit the theme. God job.</td>', 'One of the (few) flower shots that actually manage to fit the theme. God job.', '2005-10-01 00:39:30.000000', NULL, 1),
