(1754915, 236144, 42404, '<td valign="top">this isnt from the ground up</td>', 'this isnt from the ground up', '2005-10-03 02:14:50.000000', NULL, 1),
(1754921, 236505, 42404, '<td valign="top">i dont like the overexposure, or the direction of the photo, you cant see all the way up the neck, so there really isnt any point.</td>', 'i dont like the overexposure, or the direction of the photo, you cant see all the way up the neck, so there really isnt any point.', '2005-10-03 02:16:14.000000', NULL, 1),
(1754926, 235059, 30364, '<td valign="top">This is an exquisitely paradoxical image; few elements, simply composed, and executed (especially in post-processing) with restraint.  Paradoxical because these modest ingredients nevertheless result in an image loaded with interest and intellectual challenge for the viewer prepared to make the effort.  Those not so prepared will, alas, satisfy themselves with some carping about the wires.</td>', 'This is an exquisitely paradoxical image; few elements, simply composed, and executed (especially in post-processing) with restraint.  Paradoxical because these modest ingredients nevertheless result in an image loaded with interest and intellectual challenge for the viewer prepared to make the effort.  Those not so prepared will, alas, satisfy themselves with some carping about the wires.', '2005-10-03 02:22:06.000000', NULL, 1),
(1754937, 234684, 30364, '<td valign="top">There''s something appealing about it.  Nice abstract, graphic quality; symmetrical but not!  Provokes the viewer into thought (assuming the viewer is capable of such) ... and that''s a very good thing.</td>', 'There''s something appealing about it.  Nice abstract, graphic quality; symmetrical but not!  Provokes the viewer into thought (assuming the viewer is capable of such) ... and that''s a very good thing.', '2005-10-03 02:25:38.000000', NULL, 1),
(1754947, 237217, 30364, '<td valign="top">Well done for having an original thought!  It''s an OK photograph, but a terrific idea (which I think is the more important of the two).</td>', 'Well done for having an original thought!  It''s an OK photograph, but a terrific idea (which I think is the more important of the two).', '2005-10-03 02:28:45.000000', NULL, 1),
(1755002, 236384, 30364, '<td valign="top">Lovely, lush image of these gorgeous grapes.  Already I''m thinking about having a glass of their future!  It''s a juicy, tactile photograph and a very good idea for the challenge theme.  Well done.</td>', 'Lovely, lush image of these gorgeous grapes.  Already I''m thinking about having a glass of their future!  It''s a juicy, tactile photograph and a very good idea for the challenge theme.  Well done.', '2005-10-03 02:57:23.000000', NULL, 1),
(1755026, 237193, 18828, '<td valign="top">nice picture.  if anything, i''d say maybe crop a little off the right side.  doesn''t seem to be anything important there.  but maybe you tried that and it threw it off balance.  i dunno.  just a thought.</td>', 'nice picture.  if anything, i''d say maybe crop a little off the right side.  doesn''t seem to be anything important there.  but maybe you tried that and it threw it off balance.  i dunno.  just a thought.', '2005-10-03 03:13:13.000000', NULL, 1),
