(1759799, 234740, 37893, '<td valign="top">Damn! Sooo close to a ribbon! You were denied 2/1000 of a point :P Congrats buddy! Great image :)</td>', 'Damn! Sooo close to a ribbon! You were denied 2/1000 of a point :P Congrats buddy! Great image :)', '2005-10-05 01:44:55.000000', NULL, 0),
