(1761648, 237352, 35947, '<td valign="top">WOW!  Great shot!</td>', 'WOW!  Great shot!', '2005-10-05 14:17:14.000000', NULL, 0),
(1761719, 236120, 41574, '<td valign="top">Man, I can''t believe I missed out on giving this a score (I also can''t believe that one person gave it a "1," and that another gave it a "2" [I''d''ve given it a "9"]). Among a slew of building-photographs, submitted in this challenge, this shot manages to stand out as one of the best. Great job!</td>', 'Man, I can''t believe I missed out on giving this a score (I also can''t believe that one person gave it a "1," and that another gave it a "2" [I''d''ve given it a "9"]). Among a slew of building-photographs, submitted in this challenge, this shot manages to stand out as one of the best. Great job!', '2005-10-05 14:36:05.000000', NULL, 0),
